import{_ as i,C as n,o as r,c as l,ag as t,E as c,w as a,a as s}from"./chunks/framework.BSwSpTvy.js";const k=JSON.parse('{"title":"📝 Custom Rule Insertion","description":"","frontmatter":{},"headers":[],"relativePath":"features/rules.md","filePath":"features/rules.md"}'),u={name:"features/rules.md"};function d(p,e,h,g,m,f){const o=n("ZedChat");return r(),l("div",null,[e[2]||(e[2]=t(`<h1 id="📝-custom-rule-insertion" tabindex="-1">📝 Custom Rule Insertion <a class="header-anchor" href="#📝-custom-rule-insertion" aria-label="Permalink to &quot;📝 Custom Rule Insertion&quot;">​</a></h1><p>A major pain point with standard AI coding assistants is their inability to consistently follow a team&#39;s specific coding guidelines or architectural constraints.</p><p>To solve this, our Zed agent natively supports <strong>Custom Rule Insertion</strong> via <code>.rules</code> files.</p><h1 id="📝-custom-rules-rules" tabindex="-1">📝 Custom Rules (.rules) <a class="header-anchor" href="#📝-custom-rules-rules" aria-label="Permalink to &quot;📝 Custom Rules (.rules)&quot;">​</a></h1><p>Custom rules allow you to enforce project-specific coding standards, architectural constraints, and team preferences directly on the AI agent.</p><h2 id="rule-detection-injection" tabindex="-1">Rule Detection &amp; Injection <a class="header-anchor" href="#rule-detection-injection" aria-label="Permalink to &quot;Rule Detection &amp; Injection&quot;">​</a></h2><p>The agent&#39;s context engine (implemented in <code>crates/agent/src/templates.rs</code>) automatically scans your workspace root for specific rule files:</p><ul><li><strong><code>.rules</code></strong>: Global rules applied to every turn.</li><li><strong><code>.cpp_rules</code></strong>: Specific logic injected only when a C++ file is in context.</li><li><strong><code>.python_rules</code></strong>: Specific logic injected only when a Python file is in context.</li></ul><p>These files are injected at the <strong>very bottom</strong> of the system prompt. Because they appear last, they benefit from the &quot;recency bias&quot; of Large Language Models, ensuring your specific instructions take precedence over the agent&#39;s general training.</p><h2 id="visual-walkthrough" tabindex="-1">Visual Walkthrough <a class="header-anchor" href="#visual-walkthrough" aria-label="Permalink to &quot;Visual Walkthrough&quot;">​</a></h2><h3 id="enforcing-team-standards" tabindex="-1">Enforcing Team Standards <a class="header-anchor" href="#enforcing-team-standards" aria-label="Permalink to &quot;Enforcing Team Standards&quot;">​</a></h3><p>If you have a <code>.python_rules</code> file containing:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Always use Pydantic v2 for data models.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Type hints are mandatory for all public APIs.</span></span></code></pre></div><p>The agent will automatically align its output without you needing to mention these rules in the chat:</p>`,14)),c(o,null,{user:a(()=>[...e[0]||(e[0]=[s(" Write a simple User model with an email field. ",-1)])]),assistant:a(()=>[...e[1]||(e[1]=[s(" Consulting `.python_rules` for project standards... Implementing with Pydantic v2 and mandatory type hints. ",-1)])]),_:1}),e[3]||(e[3]=t('<h2 id="strategy-rules-vs-memory" tabindex="-1">Strategy: Rules vs Memory <a class="header-anchor" href="#strategy-rules-vs-memory" aria-label="Permalink to &quot;Strategy: Rules vs Memory&quot;">​</a></h2><p>| <strong><code>.rules</code> Files</strong> | Permanent team standards (Static) | Committed to Git | | <strong>SQLite Memory</strong> | Evolving codebase facts (Dynamic) | Local Project DB |</p><h2 id="workflow-impact" tabindex="-1">Workflow Impact <a class="header-anchor" href="#workflow-impact" aria-label="Permalink to &quot;Workflow Impact&quot;">​</a></h2><ul><li><strong>Team Standardization</strong>: Commit a <code>.rules</code> file to your project root to ensure every developer&#39;s AI assistant follows the same linting, naming, and architectural standards.</li><li><strong>Zero Hallucination</strong>: Proactively tell the agent about obscure project &quot;gotchas&quot; before it suggests a fix that breaks your specific environment.</li><li><strong>Automated Persona</strong>: Define the agent&#39;s tone and expertise level on a per-directory basis (e.g., &quot;Be a grumpy Senior C++ dev in <code>crates/engine</code>&quot;).</li><li><strong>Language Specificity</strong>: Add <code>.rules</code> to specific subdirectories to inject language-specific constraints only where they are needed.</li></ul>',4))])}const _=i(u,[["render",d]]);export{k as __pageData,_ as default};
